update public.learning_paths
set
  title = 'Scriptural Languages (Hebrew/Greek)',
  goal = 'Scriptural Languages (Hebrew/Greek)',
  summary = 'Students learn why Hebrew and Greek matter for scriptural interpretation and how language study changes reading, translation, theology, history, and ethics. The course builds Biblical Hebrew and Koine Greek reading fluency, then develops grammar habits, vocabulary methods, nominal and verbal systems, and genre-sensitive syntax. Students treat translation as disciplined interpretation, use lexicons, grammars, parsers, concordances, corpora, and databases critically, and learn how textual witnesses and apparatus entries affect translation without reducing scripture to uncertainty. Close reading and a translation commentary connect grammar to rhetoric, genre, theology, historical context, and responsible public communication.',
  data = $scrijson${"slug": "scriptural-languages-hebrew-greek", "title": "Scriptural Languages (Hebrew/Greek)", "description": "Students learn why Hebrew and Greek matter for scriptural interpretation and how language study changes reading, translation, theology, history, and ethics. The course builds Biblical Hebrew and Koine Greek reading fluency, then develops grammar habits, vocabulary methods, nominal and verbal systems, and genre-sensitive syntax. Students treat translation as disciplined interpretation, use lexicons, grammars, parsers, concordances, corpora, and databases critically, and learn how textual witnesses and apparatus entries affect translation without reducing scripture to uncertainty. Close reading and a translation commentary connect grammar to rhetoric, genre, theology, historical context, and responsible public communication.", "topics": [{"id": "fa1e7bc2-5817-4de4-997a-ae3b9f22b51a", "type": "topic", "title": "Orientation to Scriptural Languages: Goals, Method, Tools, and Sacred Texts", "description": "Students learn why Hebrew and Greek matter for scriptural interpretation and how language study changes reading, translation, theology, history, and ethics.", "children": [{"id": "a9d32d3d-2a7f-4b44-bf6a-03b67799e4e6", "type": "subtopic", "title": "Why original languages matter", "children": [{"id": "32029c94-915b-4695-b3c1-37ff3b9d9432", "type": "concept", "title": "Translation as interpretation"}, {"id": "ff3756b2-e593-48e2-903f-2f6f1172e1bc", "type": "concept", "title": "Scripture, history, theology, philology, and religious studies"}, {"id": "1f9b3059-5e00-46b0-b6e5-2d549c79b860", "type": "concept", "title": "Limits of word studies and responsible humility"}], "description": "Students learn how language study deepens interpretation while avoiding simplistic claims that translations are worthless."}, {"id": "73769760-4023-491d-92a6-f762c8e2994b", "type": "subtopic", "title": "Course workflow", "children": [{"id": "07b0620c-6037-4706-8a45-9dd1b9735d5a", "type": "concept", "title": "Daily reading, spaced repetition, parsing, recitation, and review"}, {"id": "2af078c7-c37f-41b9-8c0b-948f93185a4d", "type": "concept", "title": "Parallel Hebrew and Greek tracks"}, {"id": "bd4fd2a4-f2ca-420e-81be-4079dd174bd4", "type": "concept", "title": "Portfolio-based evidence of progress"}], "description": "The point is to build habits that turn language study into sustainable reading practice."}, {"id": "0c2be669-14bf-475c-92fe-081270b6591d", "type": "subtopic", "title": "Sacred text ethics", "children": [{"id": "7d373804-fea0-45c3-9c17-e0b7c4977abc", "type": "concept", "title": "Academic and confessional contexts"}, {"id": "f4234c2b-cd0b-4340-89ff-118daa71f939", "type": "concept", "title": "Respect for Jewish and Christian interpretive traditions"}, {"id": "5130320e-f5ea-430b-be2d-190188d7e2e1", "type": "concept", "title": "Citation, translation transparency, and public communication"}], "description": "Students learn to handle scriptural language with scholarly care and community awareness."}]}, {"id": "969d0015-5f18-47fc-ad3e-3b0d5a29b13e", "type": "topic", "title": "Hebrew Alphabet, Pronunciation, Transliteration, Masoretic Pointing, and Reading Fluency", "description": "This module builds the foundation for reading Biblical Hebrew accurately, including consonants, vowels, syllables, accents, and transliteration conventions.", "children": [{"id": "6da9e0d4-1f05-4245-a2b4-0af96630df77", "type": "subtopic", "title": "Writing system", "children": [{"id": "024f9948-72df-4c20-9ddf-27f53dc2022c", "type": "concept", "title": "Consonants, final forms, begadkephat letters, matres lectionis, and gutturals"}, {"id": "1d0d7ee5-6eec-46d2-bac6-008bff4209de", "type": "concept", "title": "Vowels, shewa, dagesh, maqqef, and furtive patah"}, {"id": "dd395f03-bc94-4d25-b0cb-132ca62ae34b", "type": "concept", "title": "Right-to-left reading and handwriting recognition"}], "description": "Students master the visual and phonetic foundations of Biblical Hebrew."}, {"id": "df85130b-6fb8-498f-8261-0b87b264f304", "type": "subtopic", "title": "Pronunciation and transliteration", "children": [{"id": "6b0bc20c-2f3b-48b2-a252-e4ec900eb44b", "type": "concept", "title": "Syllables, stress, accents, reduced vowels, and common pronunciation traditions"}, {"id": "e591cd86-931c-449d-b284-b7d4103eb11b", "type": "concept", "title": "Academic transliteration systems"}, {"id": "a45e0987-7a23-4f93-9b9f-714e13e6c130", "type": "concept", "title": "Names, divine names, and respectful conventions"}], "description": "The gist is to read aloud and represent Hebrew consistently."}, {"id": "f61adc56-1082-43cd-b389-dcdcd29e9312", "type": "subtopic", "title": "Fluency drills", "children": [{"id": "4fd37ae5-a8dd-4234-8a21-b21d5e9d7ee2", "type": "concept", "title": "Sight reading short clauses"}, {"id": "da71e27f-f1bb-401e-9caf-36093b0e5e1d", "type": "concept", "title": "Chanting or oral reading practice"}, {"id": "558c9af2-c872-4355-b60a-b1d04d30b864", "type": "concept", "title": "Error correction through repeated exposure"}], "description": "Students develop automatic recognition before heavy grammar work."}]}, {"id": "31dbb588-9812-45e9-a778-fffc6b69714d", "type": "topic", "title": "Greek Alphabet, Pronunciation, Breathings, Accents, and Koine Reading Fluency", "description": "Students build the foundation for reading Koine Greek through alphabet mastery, pronunciation, accent recognition, and fluent parsing of simple forms.", "children": [{"id": "1fc6dcf1-2477-418d-b556-c9f64669eade", "type": "subtopic", "title": "Writing system", "children": [{"id": "3235f642-2f57-45a6-9f86-522bd7a39408", "type": "concept", "title": "Uppercase/lowercase letters, diphthongs, iota subscript, sigma forms, and punctuation"}, {"id": "55d67d63-01a9-43ee-8cd2-c93a4287c2db", "type": "concept", "title": "Rough and smooth breathings"}, {"id": "66793813-d98a-40f4-8c3b-64fbe52291a4", "type": "concept", "title": "Manuscript and printed text awareness"}], "description": "Students master the Greek alphabet as a reading tool, not just a memorized list."}, {"id": "00bbdd78-5d42-4b7d-b63c-8c5d42827aec", "type": "subtopic", "title": "Pronunciation and accent awareness", "children": [{"id": "1d6a776e-13cc-4c7e-b8ea-b67fb67e30e3", "type": "concept", "title": "Erasmian, reconstructed, and modern pronunciation options"}, {"id": "5d503a4e-db20-4cae-8fb2-66bf72c2bf20", "type": "concept", "title": "Acute, grave, circumflex, enclitics, and stress patterns"}, {"id": "b0a38e6e-f97d-4de0-b825-0b872629c12f", "type": "concept", "title": "Reading aloud for retention"}], "description": "The point is to make Greek readable and audible."}, {"id": "c5c84b7c-cba7-4ab1-bc96-98c5ef867d4b", "type": "subtopic", "title": "Early Koine reading", "children": [{"id": "ccbbaf14-8aa7-4d37-9373-c1ac8313e312", "type": "concept", "title": "Common particles, articles, conjunctions, and high-frequency verbs"}, {"id": "20298a27-1b3c-414b-9b8a-fccda5d1a2e2", "type": "concept", "title": "Simple clauses from the New Testament and Septuagint"}, {"id": "d6951500-db0a-40f7-ad56-1e1b3a5e2854", "type": "concept", "title": "Fluency before over-analysis"}], "description": "Students begin with real phrases quickly."}]}, {"id": "4c501546-19aa-4ae4-b734-06705dd519bb", "type": "topic", "title": "Core Grammar, Morphology, and Paradigms Across Hebrew and Greek", "description": "This topic develops the grammar habits needed to recognize forms, explain their function, and move from memorized paradigms to real text reading.", "children": [{"id": "d3366440-2c3c-4882-acc0-e733e0b9303b", "type": "subtopic", "title": "Grammar metalanguage", "children": [{"id": "17b64bcf-46b0-4648-b9bd-dd0a7dbc5fb8", "type": "concept", "title": "Noun, verb, adjective, pronoun, preposition, particle, clause, phrase, and discourse"}, {"id": "4b391680-98a9-49d2-8977-67146d788d9d", "type": "concept", "title": "Person, number, gender, case, state, tense, aspect, mood, and voice"}, {"id": "d24e8bdf-142b-4803-9b3d-83edd0eae0c6", "type": "concept", "title": "Form, function, and meaning"}], "description": "Students learn the categories needed to explain what they see in texts."}, {"id": "a69b3326-638f-4bbd-9d89-52341a021138", "type": "subtopic", "title": "Paradigm learning", "children": [{"id": "d9035a3c-e23b-49e4-99fb-a9c49b4a93b7", "type": "concept", "title": "Hebrew strong verb and noun patterns"}, {"id": "1a858a61-687c-46af-9562-b21b5ca5ac11", "type": "concept", "title": "Greek declensions and principal parts"}, {"id": "d410bd5f-16f0-404d-add4-2a448892cac2", "type": "concept", "title": "Chunking, comparison, retrieval practice, and diagnostics"}], "description": "The gist is to memorize patterns intelligently."}, {"id": "e10a6abe-ee97-4c9f-9387-1b70e38d1de3", "type": "subtopic", "title": "Parsing method", "children": [{"id": "f70e0507-a5fc-4b23-85a7-e020fc5aa857", "type": "concept", "title": "Morphological tags and abbreviations"}, {"id": "5dda4948-9b48-4da3-b333-9ef2a0151156", "type": "concept", "title": "Root/stem, endings, prefixes, suffixes, and irregular forms"}, {"id": "5309fc71-b7c4-4374-82d8-9a155fdb3579", "type": "concept", "title": "Checking parsers without becoming dependent on them"}], "description": "Students learn to identify forms step by step."}]}, {"id": "58cd76d2-8f38-42ce-b036-153ec03745ae", "type": "topic", "title": "Vocabulary, Word Formation, Roots, Stems, Principal Parts, and Semantic Range", "description": "Students learn sustainable vocabulary methods and how words carry meaning through roots, stems, compounds, context, and usage rather than one-word glosses.", "children": [{"id": "3b68575c-3fdc-4a10-94f6-13cededd6791", "type": "subtopic", "title": "Vocabulary strategy", "children": [{"id": "2efef184-5edb-402e-81a1-537abcc321cf", "type": "concept", "title": "Frequency lists, spaced repetition, cognates, semantic fields, and context cards"}, {"id": "ce1a0614-673d-4393-8d03-4a4a240950d3", "type": "concept", "title": "Hebrew roots and Greek principal parts"}, {"id": "e62af5a7-ccbf-4137-a83d-6982c0e5f95a", "type": "concept", "title": "Active recall, reading exposure, and review cycles"}], "description": "Students build high-frequency recognition with long-term retention."}, {"id": "90506e9b-3b96-4c87-bb65-f8468972e4c0", "type": "subtopic", "title": "Word formation", "children": [{"id": "ed2be40d-401d-4277-a7d3-028b4e95cf70", "type": "concept", "title": "Hebrew roots, stems, nouns, adjectives, and derived forms"}, {"id": "01e55a0a-0ee0-440b-ac0e-2baf1d07be51", "type": "concept", "title": "Greek compounds, prefixes, suffixes, and verbal stems"}, {"id": "fb63c219-4f31-4741-89c5-e90030eaae15", "type": "concept", "title": "Loanwords, names, and transliterated terms"}], "description": "The point is to see how words are built and related."}, {"id": "15ecde85-d9d8-43b0-81b3-580050a5cf67", "type": "subtopic", "title": "Semantic range", "children": [{"id": "55b3ff50-6e3f-4764-a3db-0050af2cf093", "type": "concept", "title": "Lexical domain, usage, collocation, metaphor, and genre"}, {"id": "49408f82-9e06-4834-afe0-46134e591efa", "type": "concept", "title": "Polysemy, idiom, and context-sensitive meaning"}, {"id": "a565abcd-6706-4dd5-8ef0-e7be2173b20f", "type": "concept", "title": "Word-study fallacies and safeguards"}], "description": "Students move beyond one-word glosses."}]}, {"id": "e58130f7-9d6d-44bd-bdca-180a481c2456", "type": "topic", "title": "Hebrew Nominal System: Nouns, Adjectives, Pronouns, Construct Chains, and Prepositions", "description": "This module studies how Biblical Hebrew builds phrases and relationships through gender, number, state, agreement, pronominal suffixes, and particles.", "children": [{"id": "0d0cbbaa-c7b5-48d3-a851-cb9ed83b890f", "type": "subtopic", "title": "Nouns and adjectives", "children": [{"id": "5fb8fc73-61c2-493c-8409-5de388137ae8", "type": "concept", "title": "Gender, number, definiteness, state, and agreement"}, {"id": "04f832d9-bbf8-43a6-99db-69fae19c773a", "type": "concept", "title": "Adjective position and attributive/predicative function"}, {"id": "54555a46-82e8-48f3-9f5f-2d962c5a3df1", "type": "concept", "title": "Irregular nouns and common patterns"}], "description": "Students learn how Hebrew marks relationships in phrases."}, {"id": "93b81160-5220-416c-ad12-65567967fe87", "type": "subtopic", "title": "Construct chains", "children": [{"id": "411ffbbf-150a-4870-9472-997a007a52d6", "type": "concept", "title": "Construct and absolute states"}, {"id": "ff5a8407-e61c-467a-b722-98989af27015", "type": "concept", "title": "Possession, relationship, titles, and abstract constructions"}, {"id": "72ec2245-a6ee-48a6-b80b-fa7797b74786", "type": "concept", "title": "Translation choices for multi-word chains"}], "description": "The gist is to interpret one of Hebrew's most important phrase structures."}, {"id": "b7582c57-7d06-4643-8d2c-38d72ffe971a", "type": "subtopic", "title": "Pronouns and prepositions", "children": [{"id": "adec1deb-5350-4d13-a1a4-3672b6b2e25b", "type": "concept", "title": "Independent pronouns, pronominal suffixes, demonstratives, relatives, and interrogatives"}, {"id": "848a53c9-799d-442e-ac14-2415bc98f537", "type": "concept", "title": "Prefixed and independent prepositions"}, {"id": "cd45ff42-207c-492b-8888-fee33db824f3", "type": "concept", "title": "Particles, negation, and common idioms"}], "description": "Students identify compact forms that carry major interpretive weight."}]}, {"id": "4ef93e49-1bd1-42a1-b607-d62f3d7e578c", "type": "topic", "title": "Hebrew Verbal System: Binyanim, Perfect, Imperfect, Participles, Infinitives, and Weak Verbs", "description": "Students learn the central engine of Biblical Hebrew narrative, poetry, command, aspect, and clause flow.", "children": [{"id": "2cc7c29a-83ab-4dad-8968-eabc403856fc", "type": "subtopic", "title": "Strong verb system", "children": [{"id": "12c792bd-2d31-4abb-8362-afafb3e68921", "type": "concept", "title": "Qal, Niphal, Piel, Pual, Hiphil, Hophal, and Hithpael"}, {"id": "03d9870a-e52b-4070-a85e-a19bce1b6f22", "type": "concept", "title": "Perfect, imperfect, imperative, participle, infinitive construct, and infinitive absolute"}, {"id": "646f21a0-d13a-463e-bac9-04659aef4201", "type": "concept", "title": "Aspect, modality, and translation range"}], "description": "Students learn the major Hebrew verb patterns."}, {"id": "a8a36b6a-9bff-4de9-9140-c9533c61e95b", "type": "subtopic", "title": "Weak verbs", "children": [{"id": "d5966d93-dc74-45ab-bf90-46d3c824984a", "type": "concept", "title": "Gutturals, hollow verbs, geminate verbs, I-yod, I-nun, III-he, and lamed-he patterns"}, {"id": "22a1c5b2-0d84-4df0-a67b-a2a6c664363b", "type": "concept", "title": "Diagnostic clues in prefixes, vowels, and endings"}, {"id": "21c668d9-3007-4a8b-bcf0-ff075f2c9d46", "type": "concept", "title": "Parsing workflow for difficult forms"}], "description": "The point is to recognize predictable irregularity."}, {"id": "669a19b5-5bdd-4439-9dcf-2b1e63a62140", "type": "subtopic", "title": "Narrative and poetry verbs", "children": [{"id": "80d03986-05a5-40f7-a280-27f82a4399b8", "type": "concept", "title": "Wayyiqtol, weqatal, qatal, yiqtol, participles, and verbless clauses"}, {"id": "19dc95d0-fd9e-4818-9a7b-5c1ef98a3231", "type": "concept", "title": "Commands, wishes, promises, and prophetic speech"}, {"id": "277bddef-22a7-4428-accf-e5bdd45a86a0", "type": "concept", "title": "Parallelism and poetic compression"}], "description": "Students connect verbal forms to genre and discourse."}]}, {"id": "19735651-3cb3-40c1-9452-97f3ea04f8db", "type": "topic", "title": "Greek Nominal System: Cases, Articles, Pronouns, Adjectives, Participles, and Prepositions", "description": "This topic develops control of Greek phrase structure by focusing on case function, agreement, article usage, participles, and prepositional syntax.", "children": [{"id": "7ef85d9a-7917-4c48-baf4-30a563af3f9e", "type": "subtopic", "title": "Cases and declensions", "children": [{"id": "8d4f8b5d-5749-4e9b-856e-4210aaefc0d8", "type": "concept", "title": "Nominative, genitive, dative, accusative, vocative"}, {"id": "1c6072ef-cdf2-4544-9822-db86d71de567", "type": "concept", "title": "First, second, and third declensions"}, {"id": "dfc218f2-3709-48f9-a0b7-ee5a475e6360", "type": "concept", "title": "Case functions and translation choices"}], "description": "Students learn how Greek marks grammatical relationships."}, {"id": "1c402c2e-10c9-43e6-972e-3c98e7926efb", "type": "subtopic", "title": "Articles, adjectives, and pronouns", "children": [{"id": "4517133d-cb5c-4cf9-a6d3-33297e0b0554", "type": "concept", "title": "Article usage, substantival adjectives, attributive/predicate positions, and agreement"}, {"id": "f5d4bb28-6982-429a-920e-074551375e1d", "type": "concept", "title": "Personal, demonstrative, relative, interrogative, indefinite, and reflexive pronouns"}, {"id": "543bedaa-8b79-468e-9d87-033d1c2c78c6", "type": "concept", "title": "Granville Sharp and other advanced article issues as appropriate"}], "description": "The gist is to interpret Greek noun phrases accurately."}, {"id": "8bd20795-812f-44dc-ad9e-86476e785b2a", "type": "subtopic", "title": "Participles and prepositions", "children": [{"id": "658312aa-8fbf-49eb-87d9-977241367ec8", "type": "concept", "title": "Adjectival, substantival, adverbial, genitive absolute, and periphrastic participles"}, {"id": "3130901b-2f79-4260-b90f-c88158849408", "type": "concept", "title": "Prepositional phrases and case meanings"}, {"id": "a0c72fdf-d78c-49ba-891d-7d8d50ee9947", "type": "concept", "title": "Temporal, causal, concessive, conditional, and means relationships"}], "description": "Students learn structures that often carry compressed meaning."}]}, {"id": "4a673a04-4515-457a-a27d-1410c47eaf9f", "type": "topic", "title": "Greek Verbal System: Tense, Aspect, Voice, Mood, Participles, Infinitives, and Principal Parts", "description": "Students learn how Greek verbs communicate action, viewpoint, agency, condition, command, and discourse movement.", "children": [{"id": "46220f0a-d326-4362-8c31-25b1159dc7c6", "type": "subtopic", "title": "Tense and aspect", "children": [{"id": "383b0156-99ba-4936-9843-d5d0816e3dbf", "type": "concept", "title": "Present, imperfect, aorist, perfect, pluperfect, future"}, {"id": "b6d4e89b-4826-4d9f-a86a-5132128dd016", "type": "concept", "title": "Imperfective, perfective, and stative aspect"}, {"id": "a0318ec1-099c-4404-81b2-6a8fd7338337", "type": "concept", "title": "Aktionsart, context, and discourse function"}], "description": "Students learn to interpret Greek verbs without over-translating tense labels."}, {"id": "97ff4f7b-90b9-44de-ad05-3555dfac2d51", "type": "subtopic", "title": "Voice and mood", "children": [{"id": "1b961041-a992-4ddf-afce-4f4dfb3ee889", "type": "concept", "title": "Active, middle, passive, deponent, and mediopassive forms"}, {"id": "d78a3430-b4a2-4e4a-b49c-3d11331cc811", "type": "concept", "title": "Indicative, subjunctive, optative, imperative"}, {"id": "6f827476-cb1b-4ef2-90db-cced310417bb", "type": "concept", "title": "Conditionals, prohibitions, purpose, result, and exhortation"}], "description": "The point is to understand agency, possibility, command, and condition."}, {"id": "9b3c6147-729f-412d-8cfb-3b4ade4902bb", "type": "subtopic", "title": "Nonfinite forms", "children": [{"id": "39ad4615-c52a-4451-bc13-b04141b94f55", "type": "concept", "title": "Participles, infinitives, complementary infinitives, articular infinitives, and indirect discourse"}, {"id": "1b154f53-69f2-495d-9afd-84cc7c0d2cbd", "type": "concept", "title": "Principal parts and stem recognition"}, {"id": "2d34e2d8-0a89-4bf6-b725-59beb54524da", "type": "concept", "title": "Complex verbal chains and translation strategy"}], "description": "Students master forms that drive Greek syntax."}]}, {"id": "a0d31153-f29d-4035-b48a-a8faff7fedc1", "type": "topic", "title": "Syntax and Clause Structure: Hebrew Narrative/Poetry and Greek Discourse", 